CREATE TABLE IF NOT EXISTS profile (id BIGSERIAL PRIMARY KEY, "name" VARCHAR(200) NOT NULL, biography TEXT NOT NULL);
CREATE SEQUENCE IF NOT EXISTS talks_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE TABLE IF NOT EXISTS talks (talks_id BIGINT PRIMARY KEY, "k" BIGSERIAL NOT NULL, speaker_id BIGINT NOT NULL, description TEXT NOT NULL, is_published BOOLEAN DEFAULT FALSE NOT NULL, title VARCHAR(200) NOT NULL, "date" TIMESTAMP NOT NULL, money DECIMAL(1, 2) NOT NULL, "money_C" VARCHAR(3) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT fk_talks_speaker_id FOREIGN KEY (speaker_id) REFERENCES profile(id) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE SEQUENCE IF NOT EXISTS talks_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS talks_k_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;